begin;
create function private.ma_permitido(municipio text,colecao_alvo text,acao text) returns boolean language sql stable security definer set search_path='' as $$
 select auth.uid() is not null and exists(select 1 from public.ma_vinculos v join private.ma_permissoes p on p.papel=v.papel and p.colecao=colecao_alvo join public.ma_prefeituras m on m.id=v.municipio_id where v.user_id=auth.uid() and v.municipio_id=municipio and m.dados->>'status'<>'suspensa' and case acao when 'ler' then p.ler when 'gravar' then p.gravar when 'excluir' then p.excluir else false end);
$$;
revoke all on function private.ma_permitido(text,text,text) from public,anon;
grant execute on function private.ma_permitido(text,text,text) to authenticated,ma_escritor;
alter policy cadastro_leitura on public.ma_cadastros using(private.ma_permitido(municipio_id,colecao,'ler'));
alter policy escritor_cadastro_leitura on public.ma_cadastros using(private.ma_permitido(municipio_id,colecao,'ler'));
alter policy escritor_cadastro_novo on public.ma_cadastros with check(private.ma_permitido(municipio_id,colecao,'gravar'));
alter policy escritor_cadastro_edicao on public.ma_cadastros using(private.ma_permitido(municipio_id,colecao,'gravar')) with check(private.ma_permitido(municipio_id,colecao,'gravar'));
alter policy escritor_cadastro_exclusao on public.ma_cadastros using(private.ma_permitido(municipio_id,colecao,'excluir'));
create function private.ma_validar_contrato() returns trigger language plpgsql security definer set search_path='' as $$
declare contrato jsonb; campo text; opcoes jsonb; alvo text;
begin
 if TG_TABLE_NAME='ma_prefeituras' then alvo:='prefeituras';else alvo:=new.colecao;end if;
 select documento->alvo into contrato from public.ma_configuracao where id='contratos';
 if contrato is null then raise exception 'Contrato ausente' using errcode='23514';end if;
 if lower(coalesce(new.dados->>'demo','false'))='true' or lower(coalesce(new.dados->>'status_simulacao','')) in ('demo','simulado','demonstracao') then raise exception 'Dados demonstrativos proibidos' using errcode='23514';end if;
 for campo in select jsonb_array_elements_text(contrato->'required') loop
  if jsonb_typeof(new.dados->campo) is distinct from 'string' or btrim(new.dados->>campo)='' then raise exception 'Campo obrigatório: %',campo using errcode='23514';end if;
 end loop;
 for campo,opcoes in select key,value from jsonb_each(contrato->'enums') loop
  if coalesce(new.dados->>campo,'')<>'' and not opcoes @> jsonb_build_array(new.dados->campo) then raise exception 'Opção inválida: %',campo using errcode='23514';end if;
 end loop;
 if (nullif(new.dados->>'lat','') is null)<>(nullif(new.dados->>'lng','') is null) then raise exception 'Latitude e longitude devem ser informadas juntas' using errcode='23514';end if;
 if nullif(new.dados->>'lat','') is not null then
  begin
   if not ((new.dados->>'lat')::numeric between -90 and 90 and (new.dados->>'lng')::numeric between -180 and 180) then raise exception 'Coordenadas inválidas' using errcode='23514';end if;
  exception when invalid_text_representation then raise exception 'Coordenadas inválidas' using errcode='23514';end;
 end if;
 return new;
end;
$$;
revoke all on function private.ma_validar_contrato() from public,anon,authenticated;
create trigger ma_contrato_cadastro before insert or update on public.ma_cadastros for each row execute function private.ma_validar_contrato();
create trigger ma_contrato_prefeitura before insert or update on public.ma_prefeituras for each row execute function private.ma_validar_contrato();
commit;
